import { Chip, Card, CardContent, CardActions, Button, Typography, Box, TextField, Grid, Tooltip, IconButton, Popover, CardHeader, CardMedia, Switch, Link, Dialog, DialogTitle, DialogContent, DialogActions } from '@mui/material';
import './App.css';
import { useState } from 'react';
import { useCategories, useCategoryCount, useFilteredGames, useIsMiniJeux } from './hookGame';
import * as Icons from '@mui/icons-material';
import { useGlobalScores } from './App';
import ChuckNorrisFact, { HiScoreButton } from './ChuckNorrisFact';

const statusColors = {
  success: '#20b627ff',
  info: '#1b7ed0ff',
  warning: '#d6aa16ff',
  error: '#cc1b1bff',
  default: '#eeeeee'
};
const GameCard = ({ jeu, onSelect }) => {
  const color = statusColors[jeu.status] || statusColors.default;
  const Icon = Icons[jeu.icon] || Icons['SportsEsports'];
   const { getScoreByGame } = useGlobalScores();
const scoreData = getScoreByGame(jeu.id||jeu.name); // <-- important : singApp.id
              const scoreDisplay =
                scoreData?.score && scoreData.score > 0
                  ? `🏆 ${scoreData.score}`
                  : null;
  return (
    <Card
      onClick={() => onSelect(jeu)}
      sx={{
        height: '100%',
        display: 'flex',
        flexDirection: 'column',
        borderRadius: 6,
        border: `2px solid ${color}`,
        cursor: 'pointer',
        boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
        transition: 'all 0.3s ease',
        '&:hover': {
          boxShadow: `0 4px 20px ${color}80`,
          transform: 'scale(1.05)'
        }
      }}
    >
      {jeu.image && (
        <CardMedia
          component="img"
          image={jeu.image}
          alt={jeu.name}
          sx={{
            height: 140,
            objectFit: 'cover',
            borderRadius: 3,
          }}
        />
      )}
      <CardHeader
        title={
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <Typography variant="h6" component="div" sx={{ fontWeight: 600, color: '#222', flex: 1 }}>
              {jeu.name}
            </Typography>
            {jeu.regle && (
              <Tooltip
                title={
                  <Typography variant="body2" sx={{ whiteSpace: 'pre-line', maxWidth: 300 }}>
                    {jeu.regle}
                  </Typography>
                }
                arrow
                placement="top"
              >
                <IconButton
                  size="small"
                  onClick={e => e.stopPropagation()}
                  sx={{ color: '#555', ml: 1 }}
                >
                  <Icons.Info fontSize="small" />
                </IconButton>
              </Tooltip>
            )}
            <Tooltip title={jeu.status || 'indisponible'}>
              <IconButton size="small" sx={{ color: color }}>
                <Icon />
              </IconButton>
            </Tooltip>
             {scoreDisplay && (
                        <Tooltip title={"Votre meilleur score"}>
                       <Typography
                          variant="caption"
                          sx={{ ml: 2, color: '#777' }}
                        >
                          {scoreDisplay}
                        </Typography>
                         </Tooltip>
                      )}
          </Box>
        }
        subheader={
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <Typography variant="caption" sx={{ color: '#666', textTransform: 'capitalize', fontWeight: 500 }}>
              {jeu.categorie}
            </Typography>
            {jeu.isMiniJeux && (
              <Chip
                label="Mini-jeu"
                size="small"
                color="secondary"
                sx={{ ml: 1, fontWeight: 500, textTransform: 'capitalize' }}
              />
            )}
          </Box>
        }
        sx={{ pb: 0 }}
      />

      <CardContent sx={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 1 }}>
        {jeu.description && (
          <Typography
            variant="body2"
            color="text.secondary"
            sx={{ mt: 1, flexGrow: 1, overflow: 'hidden', textOverflow: 'ellipsis' }}
          >
            {jeu.description}
          </Typography>
        )}
      </CardContent>
    </Card>
  );
};


export default GameCard;


export const Regles = ({ regle }) => {
  const [anchorEl, setAnchorEl] = useState(null);

  const handlePopoverOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handlePopoverClose = () => {
    setAnchorEl(null);
  };

  if (regle == null)
    return null;

  return (
    <>
      <Box className='reglesInfo' onClick={handlePopoverOpen}>
        <Icons.InfoOutlined color='primary' />
      </Box>
      <Popover
        open={Boolean(anchorEl)}
        anchorEl={anchorEl}
        onClose={handlePopoverClose}
        anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'right',
        }}
        transformOrigin={{
          vertical: 'top',
          horizontal: 'right',
        }}
      >
        <Box className="regleText">
          {regle}
        </Box>
      </Popover>
    </>
  );
};

export const CategoryFilter = ({ categories, selected, onChange ,gamesData}) => {
    const isMiniJeux = useIsMiniJeux(gamesData);
    const [showMiniJeux, setShowMiniJeux] = useState(false);
  const getCategoryCount = useCategoryCount(gamesData);
  const toggleCategory = (cat) => {
    if (selected.includes(cat)) {
      onChange(selected.filter(c => c !== cat));
    } else {
      onChange([...selected, cat]);
    }
  };
  const isSelected = (cat) => selected.includes(cat);

  return (
    <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mb: 2 }}>
         <Switch checked={showMiniJeux} onChange={(e) => setShowMiniJeux(e.target.checked)} />
      <Typography variant="body2" sx={{ alignSelf: 'center', mr: 1 }}>
        Afficher les mini-jeux
      </Typography>
      {categories.map(cat => {
    return   (!showMiniJeux&&isMiniJeux(cat))?null: <Chip
  label={
    <>
      {cat}
      {isMiniJeux(cat) && ' 🎮'}
      <Box component="span" sx={{ 
        ml: 1, 
        bgcolor: 'rgba(255,255,255,0.3)', 
        px: 1, 
        borderRadius: 2,
        fontSize: '0.75rem'
      }}>
        {getCategoryCount(cat)}
      </Box>
    </>
  }
  onClick={() => toggleCategory(cat)}
  sx={{
    background: isSelected(cat) 
      ? (isMiniJeux(cat) 
          ? 'linear-gradient(135deg, #fa709a 0%, #fee140 100%)'
          : 'linear-gradient(135deg, #4facfe 0%, #00f2fe 100%)')
      : (isMiniJeux(cat)
          ? 'linear-gradient(135deg, #f093fb 0%, #f5576c 100%)'
          : 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)'),
    color: 'white',
    fontWeight: 600,
    border: isSelected(cat) ? '2px solid white' : 'none',
    transform: isSelected(cat) ? 'scale(1.05)' : 'scale(1)',
    boxShadow: isSelected(cat) ? '0 0 30px rgba(79,172,254,0.6)' : '0 4px 15px rgba(0,0,0,0.3)',
    transition: 'all 0.3s ease',
    '&:hover': {
      transform: 'translateY(-3px)',
      boxShadow: '0 6px 20px rgba(0,0,0,0.5)'
    }
  }}
/>
})}
     
    </Box>
  );
};

export const GamesGrid = ({ gamesData , onSelectGame }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategories, setSelectedCategories] = useState([]);
  
  const categories = useCategories(gamesData);
  const filteredGames = useFilteredGames(gamesData, searchQuery, selectedCategories);

  return (
    <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column', p: 2 }}>
      {/* Barre de recherche */}
      <TextField
        label="Rechercher un jeu"
        variant="outlined"
        value={searchQuery}
        onChange={e => setSearchQuery(e.target.value)}
        fullWidth
        size="small"
        sx={{ mb: 2 }}
      />

      {/* Filtres de catégories */}
      <CategoryFilter gamesData={gamesData}
        categories={categories}
        selected={selectedCategories}
        onChange={setSelectedCategories}
      />

      {/* Résultats */}
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        {filteredGames.length} jeu{filteredGames.length > 1 ? 'x' : ''} trouvé{filteredGames.length > 1 ? 's' : ''}
      </Typography>

      {/* Grille de jeux */}
      <Box sx={{ flex: 1, overflowY: 'auto' }}>
        <Grid container spacing={2}>
          {filteredGames.map((jeu) => (
            <Grid item xs={12} sm={6} md={4} lg={3} 
            sx={{padding:'28px'}}
            key={jeu.id}>
              <GameCard jeu={jeu} onSelect={onSelectGame} />
            </Grid>
          ))}
        </Grid>
      </Box>
    </Box>
  );
};

