import { useEffect, useState } from 'react';
import './App.css';
import { createTheme, ThemeProvider } from '@mui/material/styles';


import { Alert, AlertTitle, Box, Collapse, Grow, IconButton, Popover, Tooltip, Typography } from '@mui/material';
import { ArrowBackIos, InfoOutlined, MenuOpen } from '@mui/icons-material';
import { HiScoreButton } from './ChuckNorrisFact';
import { AppHeader, GamesGrid, Regles } from './JeuxCards';
import { GAMES_DATA } from './gameData';

const App = () => {
  const [selectedApp, setSelectedApp] = useState(null);
  const [showHint, setShowHint] = useState(false);

  useEffect(() => {
    const alreadySeen = localStorage.getItem("seenMenuHint");
    if (alreadySeen !== "true") {
      setShowHint(true);
      localStorage.setItem("seenMenuHint", "true");
    }
  }, []);
  useEffect(() => {
    document.title = "Mini Jeux de David Poilevey";
  }, []);


  const handleSelectApp = (app) => {

    setTimeout(() => { setSelectedApp(app); }, 500);
  };
  const handleToggleLeftPanel = () => {
    setSelectedApp(null)
  };

  // Crée un thème personnalisé avec les couleurs de casino
  const theme = createTheme({
    palette: {
      primary: {
        main: '#2690ceff', // Rouge foncé
      },
      secondary: {
        main: '#e78c1eff', // Saumon
      },
    },
  });
  const handleButtonKeyDown = (event) => {
    // Vérifiez si la touche tapée est la barre d'espace (code ASCII 32)
    if (event.keyCode === 32) {
      // Empêche le déclenchement du onClick
      event.preventDefault();
    }
  };
  return (
    <ThemeProvider theme={theme}>
      <div className="app-container">

        {/* Button to toggle the center panel */}

        <Box className="toggle-button" onMouseEnter={() => setShowHint(true)} onMouseOut={() => setShowHint(false)}>
          <Tooltip
            open={showHint}
            title="Clique sur ce bouton a tout instant pour retourner au menu principal"
            placement="top-end"
            arrow
            TransitionComponent={Grow}
            TransitionProps={{ timeout: 600 }}
          >
            <IconButton className="tab-button" onClick={handleToggleLeftPanel} onKeyDown={handleButtonKeyDown}
            >
              <ArrowBackIos fontSize="large" className="tab-button" />

            </IconButton>
          </Tooltip>
        </Box>

        {/* Center panel */}
        <div className="center-panel">
          <Regles regle={selectedApp?.regle} />

          <AppPanel selectedApp={selectedApp} handleSelectApp={(app) => {
            if (window.gtag) {
              window.gtag('event', 'jeu_selectionne', {
                'event_category': 'nouveauJeu',
                'event_label': app.name,
                'value': 1
              });
            }
            handleSelectApp(app)
          }} />
        </div>
      </div>
    </ThemeProvider>
  );
};

export default App;


const AppPanel = ({ selectedApp, handleSelectApp }) => {
  if (!selectedApp) {
    return <Box sx={{ height: '100vh', display: 'flex', flexDirection: 'column' }}>
      <Box sx={{
        position: 'relative',
        p: { xs: 2, md: 3 },
        background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
        overflow: 'hidden',
        boxShadow: '0 10px 30px rgba(0,0,0,0.3)',
        '&::before': {
          content: '""',
          position: 'absolute',
          top: 0, left: 0, right: 0, bottom: 0,
          background: 'radial-gradient(circle at 20% 50%, rgba(255,255,255,0.1) 0%, transparent 50%)',
          animation: 'float 8s ease-in-out infinite'
        }
      }}>
       <AppHeader />
      </Box>

      <Box sx={{ flex: 1, overflow: 'hidden' }}>
        <GamesGrid
          gamesData={GAMES_DATA}
          onSelectGame={(app) => {
            handleSelectApp(app)
          }}
        />
      </Box>
    </Box>
  }

  if (selectedApp.component != null)
    return selectedApp.component;
  return (
    <div className="app-panel">
      <h1>{selectedApp.name}</h1>
      <p>{selectedApp.description}</p>
    </div>
  );
};

