import React, { useState } from "react";
import {
  Dialog,
  DialogTitle,
  DialogContent,
  List,
  ListItem,
  ListItemButton,
  ListItemAvatar,
  Avatar,
  ListItemText,
  Typography,
  Box,
  Stack,
  Divider,
  Chip,
  Button,
  DialogActions,
  LinearProgress,
  IconButton,
  Menu,
  MenuItem,
  ListItemIcon,
  Tooltip
} from "@mui/material";
import { Bolt, Celebration, CrisisAlert, EmojiEvents, Mood, MoreVert, Refresh, Security, SentimentDissatisfied, SentimentSatisfied, SentimentVeryDissatisfied, SentimentVerySatisfiedOutlined, Shield, SwapHoriz, Visibility, Warning } from "@mui/icons-material";

const defconIcons = [
  <Shield color="success" />,   // DEFCON 1
  <Shield color="info" />,      // DEFCON 2
  <Warning color="warning" />,  // DEFCON 3
  <Warning color="error" />,    // DEFCON 4
  <CrisisAlert color="error" />     // DEFCON 5
];

const moodIcons = {
  joyeux: <SentimentSatisfied color="success" />,
  fêtard: <SentimentVerySatisfiedOutlined color="secondary" />,
  tendu: <SentimentDissatisfied color="error" />,
  rebelle: <SentimentVeryDissatisfied color="warning" />,
  studieux: <Mood color="info" />,
  neutre: <Mood color="disabled" />
};

{/* Popover/Dialog de sélection de quartier cible */ }
export const DistrictChoiceDialog = ({ open, onClose, onSelect, otherDistricts }) => {



  return (
    <Dialog open={open} onClose={onClose}>
      <DialogTitle>Choisis une cible</DialogTitle>
      <List>
        {otherDistricts.map(d => (
          <ListItem key={d.id} disablePadding>
            <ListItemButton onClick={() => onSelect(d.id)}>
              <ListItemAvatar>
                <Avatar>{d.name[0]}</Avatar>
              </ListItemAvatar>
              <ListItemText
                primary={d.name}
                secondary={`Pop: ${d.population} | Mood: ${d.mood} | Eco: ${d.santeEconomique}`}
              />
            </ListItemButton>
          </ListItem>
        ))}
      </List>
    </Dialog>
  );
};

const moodColors = {
  joyeux: "#4caf50",
  fêtard: "#ff9800",
  tendu: "#f44336",
  rebelle: "#9c27b0",
  studieux: "#2196f3",
  neutre: "#bdbdbd"
};

const actionIcons = {
  espion: <Visibility color="action" fontSize="large" />,
  sabotage: <Bolt color="error" fontSize="large" />,
  pub: <Celebration color="secondary" fontSize="large" />,
  match: <EmojiEvents color="warning" fontSize="large" />,
  // Ajoute d'autres correspondances ici
  default: <Security color="disabled" fontSize="large" />
};

export const QuartierDialog = ({
  open,
  district,
  isPlayer,
  actions,actionPoint,
  onAction,
  onClose
}) => {
  if (!district) return null;

  // Actions filtrées selon le contexte
  const availableActions = actions.filter(a =>
    isPlayer ? !a.needOther : a.needOther
  );


  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth="sm"
      fullWidth sx={{height:'80%', display:'flex',flexDirection:'column', gap:1}}
      scroll="body"
    >
      <DialogTitle sx={{flex:1, maxHeight:60}}>
        <Stack direction="row" spacing={2} alignItems="center">
          <Box
            sx={{
              width: 18, height: 18, borderRadius: "50%",
              bgcolor: moodColors[district.mood] || "#bdbdbd"
            }}
          />
          <span>
            {district.name} {isPlayer && <Chip label="Ton quartier" size="small" color="primary" />}
          </span>
          <Typography variant="caption" color={'disabled'}>{district.nickname}</Typography>
        </Stack>
      </DialogTitle>
      <DialogContent dividers  sx={{flex:5, display:'flex',flexDirection:'column', overflow:'auto'}}>
        <Stack spacing={1} sx={{ mb: 2 , maxHeight:'600px'}}>
          <Box sx={{display:"flex", width:'100%', justifyContent:'space-between'}}>
           <Typography variant="body1"><b>Population :</b> {district.population}</Typography>
           <Typography variant="body2"><b>composition :</b> {district.habitants.map(h=>(h.archetype+' ('+h.proportion*100+'%)'))}</Typography>

            </Box>
          <AttributeBar label="Réputation" value={district.reputation} color="secondary" />
          <AttributeBar label="Économie" value={district.santeEconomique} color="success" />
          <Box display="flex" alignItems="center" justifyContent="space-around" gap={1}>
            <Typography variant="body2">DEFCON</Typography>
            {defconIcons[district.defcon - 1]}
            <Typography variant="body2">Humeur</Typography>
            {moodIcons[district.mood] || <Mood color="disabled" />}
          </Box>

          <Typography variant="body2" color="text.secondary">
            {district.description || ""}
          </Typography>
        </Stack>
        <Divider sx={{ mb: 2 }} />
        <Typography variant="subtitle2" sx={{ mb: 1 }}>Actions disponibles :</Typography>
       <Box sx={{display:'flex', flexWrap:'wrap', gap:2, alignItems:'center', justifyContent:'space-evenly'}}>
          {availableActions.length === 0 && (
            <Typography variant="body2" color="text.secondary">
              Aucune action possible pour ce quartier.
            </Typography>
          )}
          {availableActions.map(action => (
            <Box
              key={action.id}
              onClick={() => {if(actionPoint>action.cost) onAction(action, district)}}
              sx={{
                p: 1, borderRadius: 2, bgcolor: "#f5f5f5", boxShadow: 1,
                maxWidth:250,
                flexDirection:'column',
                background:`${(actionPoint<action.cost)?'rgba(0,0,0,.5)':'rgb(255,250,200)'}`,
                display: "flex", alignItems: "center", justifyContent: "space-between"
                , transition: "transform 0.15s",
               "&:hover": {
                transform: `${(actionPoint>action.cost)?"scale(1.03)":"skew(-10deg,0deg)"}`,
                boxShadow: 8,
                bgcolor: `${(actionPoint>action.cost)?"#fffff5":"#955"}`
              }
              }}
            >
              <Tooltip title={action.impact}>
              <Box sx={{display:'flex', width:'100%', justifyContent:'space-around',gap:1}}>

                  {actionIcons[action.id] || actionIcons.default}
                <Typography variant="body1" fontWeight="bold">{action.name}</Typography>
                 <Chip size="small" label={`PA: ${action.cost}`} color="primary" />

              </Box>
              </Tooltip>
                <Stack direction="row" spacing={1} sx={{ mt: 0.5 }}>
                 
                  {action.profiles && action.profiles.map(profile => (
                    <Chip key={profile} size="small" label={profile} variant="outlined" />
                  ))}
                </Stack>
              </Box>
          ))}
       </Box>
      </DialogContent>
      <DialogActions sx={{flex:1, maxHeight:60}}>
        <Button onClick={onClose} color="inherit">Fermer</Button>
      </DialogActions>
    </Dialog>
  );
};



const AttributeBar = ({ label, value, color }) => (
  <Box sx={{ mb: 1 }}>
    <Box display="flex" alignItems="center" justifyContent="space-between">
      <Typography variant="body2">{label}</Typography>
      <Typography variant="body2" fontWeight="bold">{value}</Typography>
    </Box>
    <LinearProgress
      variant="determinate"
      value={Math.max(0, Math.min(100, (value + 100) / 2))}
      color={color}
      sx={{ height: 10, borderRadius: 5, mt: 0.5 }}
    />
  </Box>
);



export const MoreMenu = ({anchorEl, handleClose, handleMenu, moreAction})=>{

  return <>
 <IconButton
        aria-label="more"
        aria-controls="more-menu"
        aria-haspopup="true"
        onClick={handleMenu}
        color="inherit"
      >
        <MoreVert />
      </IconButton>
      <Menu
        id="more-menu"
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={handleClose}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
        transformOrigin={{ vertical: 'top', horizontal: 'right' }}
      >
        <MenuItem onClick={() => { handleClose(); moreAction('changerQuartier'); }}>
          <ListItemIcon><SwapHoriz fontSize="small" /></ListItemIcon>
          Changer de quartier
        </MenuItem>
        <MenuItem onClick={() => { handleClose();moreAction('reset'); }}>
          <ListItemIcon><Refresh fontSize="small" /></ListItemIcon>
          Reset
        </MenuItem>
        {/* Ajoute d'autres actions ici */}
      </Menu>
       </>
}