import { GANG_ACTIONS, RELATION_LEVELS, RESIDENT_TYPES } from "./GangData";

export const updateRelationsAndDefcon =(district, allDistricts, events=[])=> {
  let nbGuerres = 0;
  let nbRivalites = 0;
  let newLinks = { ...district.links };

  Object.entries(newLinks).forEach(([otherId, relation]) => {
    const other = allDistricts.find(d => d.id === otherId);
    if(other==null)
        return;
    // Exemples de règles :
    if (relation === "alliance" && district.defcon >2 && other.defcon > 2) {
      // Alliance peut se dégrader
      if (Math.random() < 0.2) {
        newLinks[otherId] = "rivalité";
         events.push({
        id: `${district.id}-diplomatie-${Date.now()}`,
        author: district.name,
        content: 'Rivalité confirmée avec '+other.name,
        district: district.id,
        type: "diplomatie",
        timestamp: new Date()
      });
      }
    }
    if (relation === "rivalité" && (district.defcon <=2 || other.defcon <=2)) {
      // Rivalité peut s'apaiser
      if (Math.random() < 0.1) newLinks[otherId] = "neutre";
    }
    if (relation === "rivalité" && (district.defcon >2 || other.defcon >2)) {
      // Rivalité peut dégénérer en guerre
      if (Math.random() < 0.15){

       newLinks[otherId] = "guerre";
      events.push({
        id: `${district.id}-diplomatie-${Date.now()}`,
        author: district.name,
        content: 'Entrée en guerre contre '+other.name,
        district: district.id,
        type: "diplomatie",
        timestamp: new Date()
      });
    }
    }
    if (relation === "guerre") nbGuerres++;
    if (relation === "rivalité") nbRivalites++;
  });

  // Calcul du DEFCON
  let defcon = 1;
  if (nbRivalites >= 1) defcon = 2;
   if (nbGuerres === 1 || nbRivalites >= 2) defcon = 3;
  if (nbGuerres >= 2) defcon = 4;
  if (nbGuerres >= 4) defcon = 5;
  // Bonus/malus selon événements
  // ...

  return { newLinks, defcon:defcon };
}


export const getBonusRelationnel=links=>{
    const nbGuerre = Object.values(links).filter(l=>l==='guerre').length;
    const nbRival  =  Object.values(links).filter(l=>l==='rivalité').length; 
    const nbAlliance = Object.values(links).filter(l=>l==='alliance').length;
    let sous = 0,rep=0,pop=0;
    for(let g=0;g<nbGuerre;g++)
       {
        rep-=2; pop-=Math.round(Math.random()*100)+200; sous-=50;
       }
    for(let g=0;g<nbRival;g++)
       {
        rep--; pop-=Math.round(Math.random()*100)+50; sous+=50;
       }
    for(let g=0;g<nbAlliance;g++)
       {
        rep+=3; pop+=Math.round(Math.random()*100)+50; sous+=50;
       }

    return {santeEco:sous, reputation:rep, population:pop}
}
/**
 * Ajoute une proportion qte d'habitant du type donné dans le tableau habitants,
 * seulement si la somme des proportions ne dépasse pas 1.
 * Modifie le tableau en place.
 * @param {Array} habitants - [{ type: string, proportion: number }]
 * @param {number} qte - proportion à ajouter (ex: 0.1)
 * @param {string} type - type d'habitant à ajouter
 * @returns {boolean} - true si ajout effectué, false sinon
 */
export const addIfPossible = (habitants, qte, type) => {
  const total = habitants.reduce((sum, h) => sum + h.proportion, 0);

  if (total + qte > 1) return false;

  const idx = habitants.findIndex(h => h.type === type);
  if (idx !== -1) {
    habitants[idx].proportion += qte;
  } else {
    habitants.push({ archetype:type, proportion: qte });
  }
  return true;
};

export const changeRelation=(districtA, districtB, delta)=> {
  // Récupère la relation actuelle
  const current = districtA.links[districtB.id] || "neutre";
  const idx = RELATION_LEVELS.indexOf(current);
  let newIdx = Math.max(0, Math.min(RELATION_LEVELS.length - 1, idx - delta)); // -delta car +1 = améliore
  const newRelation = RELATION_LEVELS[newIdx];
  districtA.links[districtB.id] = newRelation;
  districtB.links[districtA.id] = newRelation;
}
export const getQuartierIcons=(value, positiveIcon, negativeIcon)=> {
  const icons = [];
  const count = Math.min(5, Math.floor(Math.abs(value) / 20)); // max 10 icônes
  const icon = value >= 0 ? positiveIcon : negativeIcon;
  for (let i = 0; i < count; i++) {
    icons.push(icon);
  }
  return icons;
}
export function getMoodTendance(district) {
  // moodScores = { rebelle: 0, joyeux: 0, ... }
  const moodScores = {};
  district.habitants.forEach(h => {
    const type = RESIDENT_TYPES.find(t => t.id === h.archetype);
    if (type && type.moodBonus) {
      Object.entries(type.moodBonus).forEach(([mood, bonus]) => {
        moodScores[mood] = (moodScores[mood] || 0) + bonus * h.proportion;
      });
    }
  });
  // Trouver le mood avec le score le plus élevé
  let tendance = null;
  let max = -Infinity;
  for (const [mood, score] of Object.entries(moodScores)) {
    if (score > max) {
      max = score;
      tendance = mood;
    }
  }
  return tendance;
}

export function aiChooseAction(district, paRestants) {
  // 1. Déterminer le besoin principal
  let besoin = null;
  if (district.reputation < -30) besoin = "reputation";
  else if(district.mood === "tendu" && district.santeEconomique >40) besoin="social";
  else if (district.santeEconomique < -30) besoin = "économie";
  else if (district.defcon > 3 ) besoin = "diplomatie";
  else if (district.reputation > 40 && district.mood !== "joyeux" && district.santeEconomique >10)
       besoin = "aggression";
  if (!besoin) {
    const tendance = getMoodTendance(district);
    if (tendance === "rebelle") besoin = "aggression";
    else if (tendance === "joyeux" || tendance === "fêtard") besoin = "social";
    else if (tendance === "studieux") besoin = "économie";
    else if (tendance === "tendu") besoin = "diplomatie";
    // etc.
  }
  // ... d’autres règles selon la personnalité du quartier

  // 2. Associer profils
  let profils = [];
  if (besoin === "reputation") profils = [ "reputation"];
  else if (besoin === "économie") profils = ["économie","diplomatie"];
  else if (besoin === "social") profils = ["social","reputation"];
  else if (besoin === "diplomatie") profils = ["diplomatie"];
  else if (besoin === "aggression") profils = ["aggression", "tension"];
  else
   profils = ["aggression", "tension","diplomatie","social","reputation"];

  // 3. Filtrer les actions
  let possibles = GANG_ACTIONS.filter(
    a => a.cost <= paRestants && profils.some(p => a.profiles.includes(p))
  );
  if (possibles.length === 0) {
    possibles = GANG_ACTIONS.filter(a => a.cost <= paRestants);
  }

  // 4. Choisir au hasard parmi les actions retenues
  if (possibles.length > 0) {
    return possibles[Math.floor(Math.random() * possibles.length)];
  }
  return null;
}


